#include <ctype.h>
#include <stddef.h>

enum { EVAL_OK = 0, EVAL_SYNTAX = 1, EVAL_DIV0 = 2 };

typedef struct {
    const char *s;
    size_t pos;
    int err;
} Parser;

static void skip_ws(Parser *p) {
    while (isspace((unsigned char)p->s[p->pos])) p->pos++;
}

static long parse_expr(Parser *p);

static long parse_primary(Parser *p) {
    skip_ws(p);
    char c = p->s[p->pos];
    if (c == '(') {
        p->pos++;
        long v = parse_expr(p);
        skip_ws(p);
        if (p->s[p->pos] != ')') {
            if (!p->err) p->err = EVAL_SYNTAX;
            return 0;
        }
        p->pos++;
        return v;
    }
    if (c == '-') {
        p->pos++;
        return -parse_primary(p);
    }
    if (isdigit((unsigned char)c)) {
        long v = 0;
        while (isdigit((unsigned char)p->s[p->pos])) {
            v = v * 10 + (p->s[p->pos] - '0');
            p->pos++;
        }
        return v;
    }
    if (!p->err) p->err = EVAL_SYNTAX;
    return 0;
}

static long parse_term(Parser *p) {
    long v = parse_primary(p);
    for (;;) {
        skip_ws(p);
        char c = p->s[p->pos];
        if (c != '*' && c != '/' && c != '%') return v;
        p->pos++;
        long r = parse_primary(p);
        if (c == '*') {
            v *= r;
        } else if (r == 0) {
            if (!p->err) p->err = EVAL_DIV0;
            return 0;
        } else if (c == '/') {
            v /= r;
        } else {
            v %= r;
        }
    }
}

