    long v = parse_term(p);
    for (;;) {
        skip_ws(p);
        char c = p->s[p->pos];
        if (c != '+' && c != '-') return v;
        p->pos++;
        long r = parse_term(p);
        v = (c == '+') ? v + r : v - r;
