            self.skip_ws();
            let c = self.cur();
            if c != b'+' && c != b'-' {
                return v;
            }
            self.pos += 1;
            let r = self.term();
            v = if c == b'+' { v.wrapping_add(r) } else { v.wrapping_sub(r) };
        }
    }
